  --shadow: 0 1px 2px rgb(28 25 23 / 0.04), 0 8px 24px -12px rgb(28 25 23 / 0.12);

  --warn-bg: #fff4e0;
  --warn-border: #f2d29b;
  --warn-text: #7a4300;

  --cell-sleep-bg: #eceae4;
  --cell-sleep-fg: #a49f95;
