    --accent-soft: #29275a;
    --accent-text: #c7c9ff;
    --now: #a5b4fc;
    --shadow: 0 1px 2px rgb(0 0 0 / 0.3), 0 8px 24px -12px rgb(0 0 0 / 0.6);

    --warn-bg: #2b2113;
    --warn-border: #5a4320;
    --warn-text: #f5c77e;

    --cell-sleep-bg: #171513;
    --cell-sleep-fg: #56514a;
    --cell-sleep-hatch: rgb(255 255 255 / 0.035);
    --cell-awake-bg: #2a2723;
    --cell-awake-fg: #dcd7ce;
    --cell-awake-border: #3b3731;
    --cell-overlap-bg: #4ade80;
    --cell-overlap-fg: #032b12;
    --cell-overlap-ring: rgb(74 222 128 / 0.25);
  }
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  min-height: 100dvh;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 15px;
  line-height: 1.5;
  font-variant-numeric: tabular-nums;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

h1,
h2,
h3,
p,
ul {
  margin: 0;
}

ul {
  padding: 0;
  list-style: none;
}

button,
input,
select {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
}

:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}

