input.content:
.cell {
  position: relative;
  display: flex;
  height: var(--cell-h, 44px);
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border: 1px solid transparent;
  border-radius: 7px;
  line-height: 1.05;
  white-space: nowrap;
  user-select: none;
  transition:
    background-color 0.15s,
    color 0.15s;
}

.main {
  font-size: 13px;
  font-weight: 550;
}

.sub {
  margin-top: 2px;
  font-size: clamp(8px, 0.75vw, 10px);
  font-weight: 500;
  letter-spacing: -0.01em;
  opacity: 0.85;
}

.cell[data-state='sleeping'] {
  background-color: var(--cell-sleep-bg);
  background-image: repeating-linear-gradient(
    135deg,
    transparent 0 4px,
    var(--cell-sleep-hatch) 4px 5px
  );
  color: var(--cell-sleep-fg);
}

.cell[data-state='awake'] {
  border-color: var(--cell-awake-border);
  background: var(--cell-awake-bg);
  color: var(--cell-awake-fg);
}

.cell[data-state='overlap'] {
  background: var(--cell-overlap-bg);
  color: var(--cell-overlap-fg);
  box-shadow: 0 2px 8px -2px var(--cell-overlap-ring);
}

.cell[data-state='overlap'] .main {
  font-size: 14px;
  font-weight: 800;
}

.cell[data-state='overlap'] .sub {
  font-weight: 700;
  opacity: 0.92;
}

/* The reference city's current hour, drawn as a ring so it reads across all states. */
.cell[data-now] {
  z-index: 1;
  box-shadow: 0 0 0 2px var(--now);
}

/* A bar in the gap before the cell marks midnight in that city. */
.cell[data-new-day]::before {
  position: absolute;
  content: '';
  border-radius: 2px;
  background: var(--text);
  opacity: 0.55;
}

.cell[data-new-day][data-axis='x']::before {
  top: 5px;
  bottom: 5px;
  left: -2px;
  width: 2px;
}

.cell[data-new-day][data-axis='y']::before {
  top: -2px;
  right: 5px;
  left: 5px;
  height: 2px;
}

