input.content:
.table {
  --info-w: clamp(150px, 19vw, 216px);
  --action-w: 30px;
  --cell-h: 46px;

  display: flex;
  flex-direction: column;
  gap: 4px;
}

/* Every row shares this template and padding, which keeps all 24 columns aligned. */
.row {
  display: grid;
  grid-template-columns: var(--info-w) minmax(0, 1fr) var(--action-w);
  align-items: center;
  column-gap: 12px;
  padding: 7px 8px 7px 12px;
  border-radius: 14px;
}

.row[data-reference] {
  background: var(--surface-sunken);
}

.info {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 2px;
}

.meta {
  color: var(--text-muted);
  font-size: 0.78rem;
  white-space: nowrap;
}

.cells {
  display: grid;
  grid-template-columns: repeat(24, minmax(0, 1fr));
  gap: 2px;
}

.action {
  display: grid;
  place-items: center;
}

.remove {
  display: grid;
  width: 28px;
  height: 28px;
  padding: 0;
  place-items: center;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: var(--text-faint);
  transition:
    background-color 0.15s,
    color 0.15s;
}

.remove:hover {
  background: var(--surface-hover);
  color: var(--text);
}

