input.content:
.scroller {
  --col-min: 76px;
  --cell-h: 38px;

  max-height: min(78dvh, 900px);
  overflow: auto;
  border: 1px solid var(--border);
  border-radius: 14px;
  background: var(--surface);
}

.table {
  min-width: calc(var(--columns) * var(--col-min));
}

/* Rows share one template, so every city column lines up down all 24 hours. */
.row {
  display: grid;
  grid-template-columns: repeat(var(--columns), minmax(var(--col-min), 1fr));
}

.headRow {
  position: sticky;
  z-index: 3;
  top: 0;
  border-bottom: 1px solid var(--border);
  background: var(--surface);
}

/* Opaque slots let the reference column stay pinned while the others scroll beneath it. */
.slot {
  padding: 2px 3px;
  background: var(--surface);
}

.row > .slot:first-child {
  position: sticky;
  z-index: 2;
  left: 0;
}

.headRow > .slot:first-child {
  z-index: 4;
}

.slot[data-reference] {
  background: var(--surface-sunken);
}

.head {
  position: relative;
  display: flex;
  min-height: 74px;
  flex-direction: column;
  align-items: flex-start;
  justify-content: flex-end;
  gap: 2px;
  padding: 22px 4px 6px;
}

.meta {
  color: var(--text-muted);
  font-size: 0.72rem;
  white-space: nowrap;
}

.remove {
  position: absolute;
  top: 0;
  right: 0;
  display: grid;
  width: 26px;
  height: 26px;
  padding: 0;
  place-items: center;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: var(--text-faint);
}

.remove:hover {
  background: var(--surface-hover);
  color: var(--text);
}

