input.content:
.card {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 16px 18px;
  border: 1px solid var(--border);
  border-radius: 16px;
  background: var(--surface-sunken);
}

.success {
  border-color: color-mix(in srgb, var(--cell-overlap-bg) 35%, var(--border));
  background: color-mix(in srgb, var(--cell-overlap-bg) 9%, var(--surface));
}

.success .icon {
  color: var(--cell-overlap-fg);
  background: var(--cell-overlap-bg);
}

.warning {
  border-color: var(--warn-border);
  background: var(--warn-bg);
  color: var(--warn-text);
}

.warning .icon {
  color: var(--warn-text);
}

.column {
  flex-direction: column;
  gap: 10px;
}

.icon {
  flex: none;
  width: 30px;
  height: 30px;
  padding: 6px;
  border-radius: 50%;
}

.warning .icon {
  padding: 4px;
}

.body {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 8px;
}

.headline {
  font-size: 1.05rem;
  font-weight: 700;
  letter-spacing: -0.015em;
}

.headlineMuted {
  color: var(--text-muted);
  font-weight: 500;
}

.warning .headline {
  color: var(--warn-text);
}

.detail {
  color: var(--text-muted);
  font-size: 0.82rem;
}

.warning .detail {
  color: var(--warn-text);
  opacity: 0.9;
}

.badges {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.badge {
  padding: 3px 11px;
  border-radius: 999px;
  background: var(--cell-overlap-bg);
  color: var(--cell-overlap-fg);
  font-size: 0.85rem;
  font-weight: 700;
  white-space: nowrap;
}

.note {
  padding: 14px 18px;
  border: 1px dashed var(--border-strong);
  border-radius: 16px;
  color: var(--text-muted);
  font-size: 0.9rem;
}

.lines {
  display: flex;
  width: 100%;
  flex-direction: column;
}

.line {
  display: grid;
  grid-template-columns: minmax(96px, 168px) 76px minmax(0, 1fr);
  align-items: center;
  gap: 4px 12px;
  padding: 9px 0;
  border-top: 1px solid var(--border);
}

.lineCity {
  font-weight: 650;
}

.lineCount {
  color: var(--text-muted);
  font-size: 0.85rem;
}

.lineWarning {
  display: inline-flex;
  grid-column: 2 / -1;
  align-items: center;
  gap: 6px;
  color: var(--warn-text);
  font-size: 0.85rem;
  font-weight: 600;
}

@media (max-width: 767px) {
  .line {
    grid-template-columns: 1fr auto;
  }

  .line .badges {
    grid-column: 1 / -1;
  }

  .lineWarning {
    grid-column: 1 / -1;
  }
}

