rtk dev-browser <<'EOF'
const page = await browser.getPage("main");
await page.setViewportSize({ width: 1280, height: 900 });
await page.goto("http://localhost:9237/");
await page.evaluate(() => localStorage.clear());
await page.reload();
await page.waitForSelector('[data-testid="city-row"]');
const data = await page.evaluate(() => {
  const rows = [...document.querySelectorAll('[data-testid="city-row"]')];
  const cellsOf = (r) => [...r.querySelectorAll('[data-testid="hour-cell"]')];
  const lefts = rows.map((r) => cellsOf(r).map((c) => Math.round(c.getBoundingClientRect().left * 10) / 10));
  const aligned = lefts.every((l) => l.every((v, i) => Math.abs(v - lefts[0][i]) < 0.6));
  return {
    title: document.title,
    h1: document.querySelector('h1')?.textContent,
    h1Count: document.querySelectorAll('h1').length,
    summary: document.querySelector('[data-testid="overlap-summary"]')?.innerText,
    ranges: [...document.querySelectorAll('[data-testid="overlap-range"]')].map((e) => e.textContent),
    hint: document.querySelector('footer p')?.textContent,
    rows: rows.map((r) => ({
      name: r.querySelector('[role="rowheader"]')?.innerText.replace(/\n/g, ' | '),
      cells: cellsOf(r).length,
      states: cellsOf(r).map((c) => c.dataset.state[0]).join(''),
      firstLabels: cellsOf(r).slice(0, 4).map((c) => c.textContent),
    })),
    aligned,
    cellSize: (() => { const b = cellsOf(rows[0])[0].getBoundingClientRect(); return [b.width, b.height]; })(),
    now: [...document.querySelectorAll('[data-now]')].length,
    stored: localStorage.getItem('timezone-overlap:v1'),
  };
});
console.log(JSON.stringify(data, null, 2));
EOF

