const page = await browser.getPage("main");
await page.evaluate(() => localStorage.setItem('timezone-overlap:v1', JSON.stringify({
  cityIds: ['san-francisco', 'denpasar', 'geneva', 'mumbai', 'kathmandu', 'honolulu'], mode: 'meeting',
  settings: { wake: 7, sleep: 23, timeFormat: '12h' } })));
for (const width of [1280, 1024, 900, 768]) {
  await page.setViewportSize({ width, height: 900 });
  await page.reload();
  await page.waitForSelector('[data-testid="city-row"]');
  const r = await page.evaluate(() => {
    const cells = [...document.querySelectorAll('[data-testid="hour-cell"]')];
    let overflowing = 0; let worst = 0; const sample = [];
    for (const c of cells) {
      const cb = c.getBoundingClientRect();
      for (const child of c.children) {
        const b = child.getBoundingClientRect();
        const over = Math.max(cb.left - b.left, b.right - cb.right);
        if (over > 0.5) { overflowing++; worst = Math.max(worst, over); if (sample.length < 3) sample.push(c.textContent); }
      }
    }
    const row = document.querySelector('[data-testid="city-row"]');
    const info = row.querySelector('[role="rowheader"]').getBoundingClientRect();
    const cw = cells[0].getBoundingClientRect().width;
    return { layout: document.querySelector('[data-testid="city-row"]') ? 'desktop' : 'mobile', cellWidth: +cw.toFixed(1), infoWidth: Math.round(info.width),
      overflowing, worst: +worst.toFixed(1), sample, pageOverflowX: document.documentElement.scrollWidth > window.innerWidth,
      infoOverflow: [...document.querySelectorAll('[role="rowheader"]')].some((e) => e.scrollWidth > e.clientWidth + 1) };
  });
  console.log(width, JSON.stringify(r));
}
