import type { TimeFormat } from '../types'

const MINUTES_PER_DAY = 24 * 60

export function mod(n: number, m: number): number {
  return ((n % m) + m) % m
}

const pad2 = (n: number) => String(n).padStart(2, '0')

const formatterCache = new Map<string, Intl.DateTimeFormat>()

function getPartsFormatter(timeZone: string): Intl.DateTimeFormat {
  let formatter = formatterCache.get(timeZone)
  if (!formatter) {
    formatter = new Intl.DateTimeFormat('en-US', {
      timeZone,
      hourCycle: 'h23',
      year: 'numeric',
      month: 'numeric',
      day: 'numeric',
      hour: 'numeric',
      minute: 'numeric',
      second: 'numeric',
    })
    formatterCache.set(timeZone, formatter)
  }
  return formatter
}

/**
 * UTC offset of an IANA timezone at a given instant, in minutes east of UTC.
 * Derived from the wall clock the platform reports, so DST and fractional
 * offsets (India +5:30, Nepal +5:45) come out right.
 */
export function getUtcOffsetMinutes(timeZone: string, at: Date): number {
  const parts = getPartsFormatter(timeZone).formatToParts(at)
  const read = (type: Intl.DateTimeFormatPartTypes) => Number(parts.find((p) => p.type === type)?.value)
  const wallClockAsUtc = Date.UTC(
    read('year'),
    read('month') - 1,
    read('day'),
    read('hour') % 24,
    read('minute'),
    read('second'),
  )
  const instant = Math.floor(at.getTime() / 1000) * 1000
  return Math.round((wallClockAsUtc - instant) / 60_000)
}

/** "UTC-7", "UTC+8", "UTC+5:30", "UTC+0" */
export function formatUtcOffset(offsetMinutes: number): string {
  const sign = offsetMinutes < 0 ? '-' : '+'
  const abs = Math.abs(offsetMinutes)
  const hours = Math.floor(abs / 60)
  const minutes = abs % 60
  return `UTC${sign}${hours}${minutes ? `:${pad2(minutes)}` : ''}`
}

/** Compact hour label used in summaries and selects: "9am", "12pm" or "09:00". */
export function formatHour(hour: number, format: TimeFormat): string {
  if (format === '24h') return `${pad2(hour)}:00`
  return `${hour % 12 || 12}${hour < 12 ? 'am' : 'pm'}`
}

export interface HourParts {
  /** Large digits shown in a grid cell. */
  main: string
  /** Small suffix: minutes for fractional offsets and/or am/pm. */
  sub: string
}

export function getHourParts(hour: number, minute: number, format: TimeFormat): HourParts {
  const minutes = minute ? `:${pad2(minute)}` : ''
  if (format === '24h') return { main: pad2(hour), sub: minutes }
  return { main: String(hour % 12 || 12), sub: `${minutes}${hour < 12 ? 'am' : 'pm'}` }
}

/** "7:42 PM" or "19:42" */
export function formatTimeOfDay(hour: number, minute: number, format: TimeFormat): string {
  if (format === '24h') return `${pad2(hour)}:${pad2(minute)}`
  return `${hour % 12 || 12}:${pad2(minute)} ${hour < 12 ? 'AM' : 'PM'}`
}

/** Wall-clock time in a zone at a UTC minute count. */
export function formatClock(utcMinutes: number, offsetMinutes: number, format: TimeFormat): string {
  const local = mod(utcMinutes + offsetMinutes, MINUTES_PER_DAY)
  return formatTimeOfDay(Math.floor(local / 60), local % 60, format)
}

/** Hour (0–23) it currently is in a zone with the given offset. */
export function currentHour(utcMinutes: number, offsetMinutes: number): number {
  return Math.floor(mod(utcMinutes + offsetMinutes, MINUTES_PER_DAY) / 60)
}

import { describe, expect, it } from 'vitest'
import {
  currentHour,
  formatClock,
  formatHour,
  formatUtcOffset,
  getHourParts,
  getUtcOffsetMinutes,
} from './time'

const summer = new Date('2026-09-29T12:00:00Z')
const winter = new Date('2026-01-15T12:00:00Z')

describe('getUtcOffsetMinutes', () => {
  it('handles whole-hour zones', () => {
    expect(getUtcOffsetMinutes('Asia/Makassar', summer)).toBe(8 * 60)
    expect(getUtcOffsetMinutes('Asia/Tokyo', winter)).toBe(9 * 60)
  })

  it('handles fractional offsets', () => {
    expect(getUtcOffsetMinutes('Asia/Kolkata', summer)).toBe(5 * 60 + 30)
    expect(getUtcOffsetMinutes('Asia/Kathmandu', summer)).toBe(5 * 60 + 45)
  })

  it('follows daylight saving time for the given date', () => {
    expect(getUtcOffsetMinutes('America/Los_Angeles', summer)).toBe(-7 * 60)
    expect(getUtcOffsetMinutes('America/Los_Angeles', winter)).toBe(-8 * 60)
    expect(getUtcOffsetMinutes('Europe/Zurich', summer)).toBe(2 * 60)
    expect(getUtcOffsetMinutes('Europe/Zurich', winter)).toBe(60)
  })

  it('does not break at midnight UTC', () => {
    expect(getUtcOffsetMinutes('Europe/London', new Date('2026-07-01T00:00:00Z'))).toBe(60)
    expect(getUtcOffsetMinutes('Pacific/Honolulu', new Date('2026-07-01T00:00:00Z'))).toBe(-600)
  })
})

describe('formatUtcOffset', () => {
  it.each([
    [-420, 'UTC-7'],
    [480, 'UTC+8'],
    [0, 'UTC+0'],
    [330, 'UTC+5:30'],
    [345, 'UTC+5:45'],
    [-570, 'UTC-9:30'],
  ])('%i -> %s', (minutes, label) => {
    expect(formatUtcOffset(minutes)).toBe(label)
  })
})

describe('hour formatting', () => {
  it('formats compact hour labels', () => {
    expect(formatHour(0, '12h')).toBe('12am')
    expect(formatHour(9, '12h')).toBe('9am')
    expect(formatHour(12, '12h')).toBe('12pm')
    expect(formatHour(23, '12h')).toBe('11pm')
    expect(formatHour(0, '24h')).toBe('00:00')
    expect(formatHour(9, '24h')).toBe('09:00')
  })

