    expect(getHourParts(7, 0, '12h')).toEqual({ main: '7', sub: 'am' })
    expect(getHourParts(0, 0, '12h')).toEqual({ main: '12', sub: 'am' })
    expect(getHourParts(13, 30, '12h')).toEqual({ main: '1', sub: ':30pm' })
    expect(getHourParts(7, 0, '24h')).toEqual({ main: '07', sub: '' })
    expect(getHourParts(13, 45, '24h')).toEqual({ main: '13', sub: ':45' })
  })

  it('formats clocks and the current hour from a UTC minute count', () => {
    const utcMinutes = Date.UTC(2026, 8, 29, 19, 42) / 60_000
    expect(formatClock(utcMinutes, 120, '12h')).toBe('9:42 PM')
    expect(formatClock(utcMinutes, 120, '24h')).toBe('21:42')
    expect(formatClock(utcMinutes, 330, '12h')).toBe('1:12 AM')
    expect(currentHour(utcMinutes, -420)).toBe(12)
  })
})

import type { CellModel, CellState } from '../lib/overlap'
import { formatTimeOfDay, getHourParts } from '../lib/time'
import type { TimeFormat } from '../types'
import styles from './HourCell.module.css'

const STATE_LABEL: Record<CellState, string> = {
  overlap: 'Overlap',
  awake: 'Awake',
  sleeping: 'Sleeping',
}

const DAY_NOTE: Record<number, string> = { [-1]: ' (yesterday)', 1: ' (tomorrow)' }

interface Props {
  cell: CellModel
  cityName: string
  format: TimeFormat
  isNow: boolean
  /** True when the local calendar day changes at this cell. */
  startsNewDay: boolean
  /** Direction the hours run in: along a row (desktop) or down a column (mobile). */
  axis: 'x' | 'y'
}

export function HourCell({ cell, cityName, format, isNow, startsNewDay, axis }: Props) {
  const { main, sub } = getHourParts(cell.hour, cell.minute, format)
  const time = formatTimeOfDay(cell.hour, cell.minute, format)
  const label = `${cityName}: ${time}${DAY_NOTE[cell.dayShift] ?? ''}, ${STATE_LABEL[cell.state].toLowerCase()}`

  return (
    <div
      role="cell"
      className={styles.cell}
      data-testid="hour-cell"
      data-state={cell.state}
      data-ref-hour={cell.refHour}
      data-now={isNow || undefined}
      data-new-day={startsNewDay || undefined}
      data-axis={axis}
      title={label}
      aria-label={label}
    >
      <span className={styles.main}>{main}</span>
      {sub && <span className={styles.sub}>{sub}</span>}
    </div>
  )
}

