  scroller.scrollLeft = 200; await new Promise((r) => setTimeout(r, 100));
  const afterX = { scrollLeft: scroller.scrollLeft, refLeft: +(refCol().left - sr.left).toFixed(1) };
  const s = getComputedStyle(document.querySelectorAll('[data-testid="city-column"]')[0]);
  const stickyEls = [...scroller.querySelectorAll('*')].filter((e) => getComputedStyle(e).position === 'sticky').length;
  return { before, afterX, refColPosition: s.position, stickyEls,
