    mode: document.querySelector('input[name="mode"]:checked')?.value,
    format: document.querySelector('input[name="time-format"]:checked')?.value,
    wake: document.querySelectorAll('select')[0].value, sleep: document.querySelectorAll('select')[1].value,
    summary: document.querySelector('[data-testid="overlap-summary"]')?.textContent.replace(/\s+/g, ' '),
    ranges: [...document.querySelectorAll('[data-testid="overlap-range"]')].map((e) => e.textContent),
    overlapCells: rows.map((r) => r.querySelectorAll('[data-state="overlap"]').length),
    hint: [...document.querySelectorAll('*')].some((e) => e.children.length === 0 && e.textContent === 'Green cells = everyone awake'),
  };
});
await page.reload();
await page.waitForSelector('[data-testid="city-row"]');
console.log(JSON.stringify({ state, errors }, null, 1));
